// src/jsx/GroupChat.jsx
import { useEffect, useState, useRef } from "react";
import { db } from "../js/firebaseConfig";
import { collection, addDoc, serverTimestamp, query, onSnapshot, orderBy, doc, getDoc, setDoc } from "firebase/firestore";
import useSearchUsers from "../hooks/useSearchUsers";
import Avatar from "./Avatar";
import { uploadMessageMedia } from "../js/supabaseUpload";

export default function GroupChat({ group, currentUser, onClose }) {
    const { allUsers } = useSearchUsers();
    const [messages, setMessages] = useState([]);
    const [text, setText] = useState("");
    const [file, setFile] = useState(null);
    const [previewUrl, setPreviewUrl] = useState("");
    const [uploading, setUploading] = useState(false);
    const listRef = useRef(null);

    useEffect(() => {
        const isMember = group.members?.some(m => m.id === currentUser.uid) || group.members?.includes?.(currentUser.uid);
        if (!isMember) {
            alert("Você não é membro deste grupo!");
            onClose();
            return;
        }
    }, [group, currentUser.uid, onClose]);

    useEffect(() => {
        const messagesRef = collection(db, `groups/${group.id}/messages`);
        const q = query(messagesRef, orderBy("createdAt", "asc"));
        const unsub = onSnapshot(q, snap => {
            setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
            setTimeout(() => {
                if (listRef.current) listRef.current.scrollTop = listRef.current.scrollHeight;
            }, 50);
        });
        return () => unsub();
    }, [group.id]);

    const onSelectFile = (e) => {
        const f = e.target.files[0];
        if (!f) return;
        const maxMB = 40;
        if (f.size > maxMB * 1024 * 1024) {
            alert(`Arquivo muito grande (limite ${maxMB} MB).`);
            return;
        }
        setFile(f);
        setPreviewUrl(URL.createObjectURL(f));
    };

    const send = async () => {
        if (!text.trim() && !file) return;
        setUploading(true);
        try {
            let mediaUrl = "";
            let type = "text";

            if (file) {
                mediaUrl = await uploadMessageMedia(file, `group_${group.id}`);
                const lower = file.type.toLowerCase();
                if (lower.startsWith("image/")) type = "image";
                else if (lower.startsWith("video/")) type = "video";
                else type = "file";
            }

            await addDoc(collection(db, `groups/${group.id}/messages`), {
                text: text?.trim() || "",
                type,
                url: mediaUrl || "",
                from: currentUser.uid,
                createdAt: serverTimestamp()
            });

            // update group lastMessage
            await setDoc(doc(db, "groups", group.id), {
                lastMessage: text?.trim() || (type === "image" ? "[imagem]" : "[arquivo]"),
                lastUpdated: serverTimestamp()
            }, { merge: true });

            setText("");
            setFile(null);
            if (previewUrl) { URL.revokeObjectURL(previewUrl); setPreviewUrl(""); }
        } catch (err) {
            console.error("Erro ao enviar mensagem de grupo:", err);
            alert("Erro: " + err.message);
        } finally {
            setUploading(false);
        }
    };

    const findUserById = id => allUsers?.find(u => u.id === id);

    return (
        <>
            <div className="chat-header">
                <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <button onClick={onClose} style={{ background: "transparent", border: "none", color: "white", fontSize: 18 }}>←</button>
                    <Avatar user={null} label={group.name} size={44} />
                    <div>
                        <div style={{ fontWeight: 700 }}>{group.name}</div>
                        <div style={{ fontSize: 12, opacity: 0.9 }}>{(group.members && group.members.length) ? `${group.members.length} membros` : ""}</div>
                    </div>
                </div>
            </div>

            <div className="chat-box" ref={listRef}>
                {messages.map(m => {
                    const isMe = m.from === currentUser.uid;
                    const sender = findUserById(m.from);
                    return (
                        <div key={m.id} style={{ display: "flex", marginBottom: 8, alignItems: "flex-end", justifyContent: isMe ? "flex-end" : "flex-start" }}>
                            {!isMe && (
                                <div style={{ marginRight: 8 }}>
                                    <Avatar user={sender} size={36} />
                                </div>
                            )}

                            <div style={{ maxWidth: "75%" }}>
                                <div className={`msg ${isMe ? "me" : "other"}`}>
                                    {!isMe && <div style={{ fontSize: 12, fontWeight: 700, marginBottom: 6 }}>{sender?.nome || sender?.email || "Usuário"}</div>}

                                    {m.type === "image" && m.url ? (
                                        <img src={m.url} alt="img" style={{ maxWidth: "100%", borderRadius: 8 }} />
                                    ) : m.type === "video" && m.url ? (
                                        <video src={m.url} controls style={{ maxWidth: "100%", borderRadius: 8 }} />
                                    ) : (
                                        <div style={{ whiteSpace: "pre-wrap" }}>{m.text}</div>
                                    )}
                                </div>

                                <div className="hora" style={{ textAlign: isMe ? "right" : "left" }}>
                                    {m.createdAt?.toDate ? m.createdAt.toDate().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) : ""}
                                </div>
                            </div>

                            {isMe && <div style={{ width: 36, marginLeft: 8 }} />}
                        </div>
                    );
                })}
            </div>

            <div className="chat-input" style={{ flexDirection: "column", gap: 8 }}>
                {previewUrl && (
                    <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
                        {file && file.type.startsWith("image/") && <img src={previewUrl} alt="preview" style={{ width: 120, height: 80, objectFit: "cover", borderRadius: 8 }} />}
                        {file && file.type.startsWith("video/") && <video src={previewUrl} style={{ width: 160, height: 100, borderRadius: 8 }} controls />}
                        <div>
                            <div style={{ fontSize: 13, fontWeight: 700 }}>{file.name}</div>
                            <div style={{ fontSize: 12, color: "#666" }}>{(file.size / 1024 / 1024).toFixed(2)} MB</div>
                        </div>
                        <button onClick={() => { setFile(null); URL.revokeObjectURL(previewUrl); setPreviewUrl(""); }} style={{ marginLeft: "auto" }}>Remover</button>
                    </div>
                )}

                <div style={{ display: "flex", width: "100%", gap: 8 }}>
                    <input value={text} onChange={e => setText(e.target.value)} placeholder="Mensagem..." style={{ flex: 1, padding: 12, borderRadius: 25, border: "1px solid #ccc" }} />
                    <label style={{ display: "inline-flex", alignItems: "center", gap: 8, cursor: "pointer", background: "#fff", padding: "8px 12px", borderRadius: 20, border: "1px solid #ccc" }}>
                        📎
                        <input type="file" accept="image/*,video/*" style={{ display: "none" }} onChange={onSelectFile} />
                    </label>
                    <button onClick={send} disabled={uploading} style={{ padding: "10px 16px", borderRadius: 25, background: "#075E54", color: "#fff", border: "none" }}>
                        {uploading ? "Enviando..." : "Enviar"}
                    </button>
                </div>
            </div>
        </>
    );
}
